<template><div><PageHeader title="Learner profile" description="Enrollment, attendance, assessments and certificate history."><template #actions><button class="btn secondary">Edit profile</button><button class="btn primary" @click="push('Certificate generation queued.')">Generate certificate</button></template></PageHeader><div class="card"><div class="profile-hero"><Avatar :name="learner.name" size="lg"/><div class="grow"><h2>{{learner.name}}</h2><p class="muted">{{learner.email}} · {{learner.company}}</p><div class="chip-row"><span class="chip">{{learner.course}}</span><StatusBadge :status="learner.status"/></div></div><div><span class="status-badge status-success">92% attendance</span></div></div><div class="metric-strip"><div><span>Active courses</span><strong>1</strong></div><div><span>Attendance</span><strong>{{learner.attendance}}%</strong></div><div><span>Assessment</span><strong>94%</strong></div><div><span>Certificates</span><strong>2</strong></div></div><div class="tabs"><button class="active">Overview</button><button>Enrollments</button><button>Attendance</button><button>Assessments</button><button>Certificates</button><button>Documents</button><button>Activity</button></div><div class="card-pad"><div class="grid-2" style="margin-top:0"><div><h3 style="font-size:15px">Current course</h3><div class="info-list" style="margin-top:14px"><div class="info-box"><span>Course</span><strong>Laravel Fundamentals</strong></div><div class="info-box"><span>Batch</span><strong>2026-09-A</strong></div><div class="info-box"><span>Progress</span><strong>78%</strong></div><div class="info-box"><span>Next session</span><strong>20 Sep · 10:00 AM</strong></div></div></div><div><h3 style="font-size:15px">Recent activity</h3><div class="timeline" style="margin-top:14px"><div class="timeline-item"><strong>Certificate ready</strong><p>Laravel Fundamentals · 8 min ago</p></div><div class="timeline-item"><strong>Attendance recorded</strong><p>Session #1842 · today</p></div><div class="timeline-item"><strong>Assessment completed</strong><p>Final assessment · 15 Sep</p></div></div></div></div></div></div></div></template>
<script setup lang="ts">import {computed} from 'vue';import {useRoute} from 'vue-router';import PageHeader from '../components/PageHeader.vue';import Avatar from '../components/Avatar.vue';import StatusBadge from '../components/StatusBadge.vue';import {learners} from '../data/mock';import {useToast} from '../composables/useToast';const route=useRoute();const learner=computed(()=>learners.find(l=>l.id===Number(route.params.id))||learners[0]);const {push}=useToast()</script>
